async function saveMemory(i){const m=state.memories.find(x=>x.id===i);if(!m)return;const start=$('#mDate').value,end=$('#mEndDate').value||start;if(start&&end&&end<start){toast('تاريخ النهاية لا يمكن أن يكون قبل البداية.');return}m.title=$('#mTitle').value.trim()||'ذكرى بدون اسم';m.date=start;m.endDate=start?end:'';m.place=$('#mPlace').value.trim();m.description=$('#mDesc').value.trim();await save();closeModal();toast('تم حفظ الذكرى.');if(section==='memories'||section==='home'||section==='calendar')renderNoAnim()}
async function saveAlbum(){const title=$('#albumTitle').value.trim();if(!title){toast('اكتب اسم الألبوم.');return}if(state.memories.some(m=>String(m.title||'').trim()===title)){toast('يوجد ألبوم بهذا الاسم بالفعل.');return}state.memories.unshift({id:id('mem'),title,date:'',endDate:'',place:'',description:'',album:title,photoIds:[]});await save();closeModal();toast('تم إنشاء الألبوم.');renderNoAnim()}
function updateSelectionCount(){const el=$('#selectionCount');if(el)el.textContent=`${selectedPhotos.size} محددة`}
function selectAllPhotos(){const m=state.memories.find(x=>x.id===currentMemoryId);if(!m)return;selectedPhotos=new Set(photoFor(m).map(p=>p.id));document.querySelectorAll('.photo-select').forEach(x=>x.checked=true);updateSelectionCount()}
