function requireSelection(){if(!selectedPhotos.size){toast('حدد صورة واحدة على الأقل.');return false}return true}
async function removeFromAlbum(){if(!requireSelection())return;const m=state.memories.find(x=>x.id===currentMemoryId);if(!m)return;m.photoIds=m.photoIds.filter(pid=>!selectedPhotos.has(pid));for(const pid of selectedPhotos){const p=photos.get(pid);if(p){p.manualAlbum=true;p.album='غير مصنف';await put('photos',p)}}selectedPhotos.clear();await save();toast('تمت إزالة الصور من هذا الألبوم دون حذف الأصل.');renderNoAnim()}
function moveSelected(){if(!requireSelection())return;const m=state.memories.find(x=>x.id===currentMemoryId);if(!m)return;const targets=state.memories.filter(x=>x.id!==m.id);modal(`<h2>نقل الصور المحددة</h2><p class="meta">${selectedPhotos.size} صورة سيتم نقلها من «${esc(m.title||'الذكرى الحالية')}».</p><div class="cards">${targets.length?targets.map(t=>`<button class="card selectable-card" data-action="moveToAlbum" data-id="${t.id}"><b>📁 ${esc(t.title||'ألبوم')}</b><small class="meta">${photoFor(t).length} صورة</small></button>`).join(''):`<div class="empty">أنشئ ألبومًا أولًا.</div>`}</div><div class="actions"><button class="btn primary" data-action="createAlbumAndMove">＋ إنشاء ألبوم ونقل</button><button class="btn" data-action="closeModal">إلغاء</button></div>`) }
async function moveToAlbum(targetId){const m=state.memories.find(x=>x.id===currentMemoryId),t=state.memories.find(x=>x.id===targetId);if(!m||!t)return;if(t.id===m.id)return;t.album=t.album||t.title||'';m.photoIds=m.photoIds.filter(pid=>!selectedPhotos.has(pid));for(const pid of selectedPhotos){if(!t.photoIds.includes(pid))t.photoIds.push(pid);const p=photos.get(pid);if(p){p.manualAlbum=true;p.album=t.album||t.title||'غير مصنف';await put('photos',p)}}selectedPhotos.clear();await save();closeModal();toast(`تم نقل الصور إلى «${t.title||'الألبوم'}».`);renderNoAnim()}
function createAlbumAndMove(){const ids=[...selectedPhotos],from=currentMemoryId;modal(`<h2>إنشاء ألبوم ونقل الصور</h2>${field('albumTitle2','اسم الألبوم','','text')}<div class="actions"><button class="btn primary" data-action="saveAlbumMove" data-from="${from}" data-ids="${esc(JSON.stringify(ids))}">إنشاء ونقل</button><button class="btn" data-action="closeModal">إلغاء</button></div>`)}
async function saveAlbumMove(from,ids){const title=$('#albumTitle2').value.trim();if(!title){toast('اكتب اسم الألبوم.');return}if(state.memories.some(m=>String(m.title||'').trim()===title)){toast('يوجد ألبوم بهذا الاسم بالفعل.');return}const t={id:id('mem'),title,date:'',endDate:'',place:'',description:'',album:title,photoIds:[]};state.memories.unshift(t);const m=state.memories.find(x=>x.id===from);for(const pid of ids){if(m)m.photoIds=m.photoIds.filter(x=>x!==pid);t.photoIds.push(pid);const p=photos.get(pid);if(p){p.manualAlbum=true;p.album=title;await put('photos',p)}}selectedPhotos.clear();await save();closeModal();toast(`تم إنشاء «${title}» ونقل الصور إليه.`);renderNoAnim()}
async function excludeSelected(){if(!requireSelection())return;const m=state.memories.find(x=>x.id===currentMemoryId);const ids=[...selectedPhotos];if(!m)return;if(!confirm('استبعاد الصور من فهرس OsRa؟ الصور الأصلية لن تُحذف من الجهاز.'))return;for(const mem of state.memories)mem.photoIds=(mem.photoIds||[]).filter(pid=>!selectedPhotos.has(pid));for(const pid of ids){const p=photos.get(pid);if(!p)continue;p.excluded=true;state.excludedPhotos.push({key:exclusionKey(p.relPath,p.size,p.lastModified),relPath:p.relPath,size:p.size,lastModified:p.lastModified,name:p.name});await put('photos',p)}state.excludedPhotos=[...new Map(state.excludedPhotos.map(x=>[x.key,x])).values()];selectedPhotos.clear();await save();toast('تم استبعاد الصور من الفهرس دون حذف الأصل.');renderNoAnim()}
async function reorderPhoto(pid,dir){const m=state.memories.find(x=>x.id===currentMemoryId);if(!m)return;const arr=m.photoIds||[],i=arr.indexOf(pid),j=i+dir;if(i<0||j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]];await save();renderNoAnim()}
async function restoreExcluded(){if(!state.excludedPhotos.length)return;for(const p of photos.values()){if(p.excluded){p.excluded=false;if(!p.manualAlbum)ensureMemory(p.album,p.id);await put('photos',p)}}state.excludedPhotos=[];await save();toast('تم إلغاء الاستبعاد. شغّل الفحص لإظهار الصور مجددًا.');renderNoAnim()}
async function saveDream(i){let d=i?state.dreams.find(x=>x.id===i):null;if(!d){d={id:id('dream')};state.dreams.unshift(d)}d.title=$('#dTitle').value.trim()||'حلم';d.targetDate=$('#dDate').value;d.progress=Math.max(0,Math.min(100,Number($('#dProgress').value||0)));d.note=$('#dNote').value.trim();d.done=d.progress>=100;await save();closeModal();renderNoAnim()}
async function saveSettings(){for(const x of ['startDate','engagementDate','birthdayRania'])state.settings[x]=$('#set'+(x==='startDate'?'Start':x==='engagementDate'?'Eng':'Birth')).value;for(const [k,id2] of [['osamaPhone','setOsama'],['raniaPhone','setRania'],['whatsappUrl','setWA']])state.settings[k]=$('#'+id2).value.trim();await save();toast('تم حفظ الإعدادات.');renderNoAnim()}
