async function hideMemory(i){const m=state.memories.find(x=>x.id===i);if(!m)return;if(!confirm(`إخفاء «${m.title||'هذه الذكرى'}»؟
لن تُحذف الذكرى أو صورها الأصلية.`))return;m.hidden=true;await save();selectedPhotos.clear();currentMemoryId=null;toast('تم إخفاء الذكرى/المجلد دون حذف أي بيانات.');renderNoAnim()}
async function unhideMemory(i){const m=state.memories.find(x=>x.id===i);if(!m)return;m.hidden=false;await save();toast('تم إظهار الذكرى/المجلد مرة أخرى.');renderNoAnim()}
function hiddenMemories(){const hs=state.memories.filter(m=>m.hidden);modal(`<h2>الذكريات والمجلدات المخفية</h2>${hs.length?`<div class="cards">${hs.map(m=>`<div class="card"><h3>${esc(m.title||'ذكرى')}</h3><div class="meta">${esc(rangeLabel(m))}${m.album?' • مجلد: '+esc(m.album):''}</div><div class="actions"><button class="btn small primary" data-action="unhideMemory" data-id="${m.id}">إظهار</button></div></div>`).join('')}</div>`:`<div class="empty">لا توجد ذكريات أو مجلدات مخفية.</div>`}<div class="actions"><button class="btn" data-action="closeModal">إغلاق</button></div>`)}
async function shareMemory(i){const m=state.memories.find(x=>x.id===i);if(!m)return;if(!libraryHandle){toast('اربط مجلد الصور أولًا.');return}if(!navigator.share||!navigator.canShare){toast('مشاركة الملفات غير مدعومة في هذا المتصفح. استخدم Chrome على Android.');return}if(!(await permission())){toast('يجب السماح لـ OsRa بقراءة مجلد الصور أولًا.');return}const ids=selectedPhotos.size?[...selectedPhotos]:photoFor(m).map(p=>p.id);if(!ids.length){try{await navigator.share({title:m.title||'ذكرى من OsRa',text:rangeLabel(m)+(m.description?'\n'+m.description:'')})}catch(e){if(e?.name!=='AbortError')toast('تعذر فتح المشاركة.')}return}toast(`جارٍ تجهيز ${ids.length} صورة للمشاركة…`);const files=[];for(const pid of ids){const p=photos.get(pid);if(!p?.relPath)continue;try{const dir=await resolve(libraryHandle,p.relPath);const f=await dir.getFile();files.push(new File([f],p.name,{type:f.type||'application/octet-stream',lastModified:f.lastModified}))}catch(e){console.warn('share file skipped',pid,e)}}if(!files.length){toast('تعذر فتح الصور الأصلية من المجلد المرتبط. شغّل الفحص وأعد المحاولة.');return}const data={files,title:m.title||'ذكرى من OsRa',text:rangeLabel(m)};if(!navigator.canShare({files})){toast('الجهاز لا يقبل مشاركة هذه المجموعة كاملة. جرّب تحديد عدد أقل من الصور.');return}try{await navigator.share(data);toast('تم إرسال الصور إلى قائمة المشاركة.')}catch(e){if(e?.name!=='AbortError')toast('تعذر إتمام المشاركة.')}}
async function chooseBackup(){if(!window.showSaveFilePicker){toast('اختيار مكان ثابت غير مدعوم في هذا المتصفح؛ استخدم Chrome حديث على Android وسيظهر التنزيل العادي كبديل.');return false}try{const h=await window.showSaveFilePicker({suggestedName:`OsRa_Backup_${today()}.json`,types:[{description:'OsRa Backup',accept:{'application/json':['.json']}}],excludeAcceptAllOption:false});backupFileHandle=h;const text=JSON.stringify(backupPayload(),null,2);const w=await h.createWritable();await w.write(text);await w.close();backupMeta={lastSavedAt:Date.now(),lastAutoFileAt:Date.now()};await put('library',{key:'backup',handle:h,name:h.name,lastSavedAt:backupMeta.lastSavedAt,lastAutoFileAt:backupMeta.lastAutoFileAt});toast('تم تحديد مكان النسخة وحفظها بنجاح.');renderNoAnim();return true}catch(e){if(e?.name==='AbortError')toast('تم إلغاء اختيار مكان النسخة الاحتياطية.');else{console.error(e);toast('تعذر حفظ النسخة في الملف المحدد.')}return false}}
async function writeBackupToHandle(forcePrompt=false){if(!backupFileHandle)return false;try{let q=await backupFileHandle.queryPermission({mode:'readwrite'});if(q!=='granted'&&forcePrompt)q=await backupFileHandle.requestPermission({mode:'readwrite'});if(q!=='granted')return false;const w=await backupFileHandle.createWritable();await w.write(JSON.stringify(backupPayload(),null,2));await w.close();backupMeta.lastSavedAt=Date.now();backupMeta.lastAutoFileAt=Date.now();await put('library',{key:'backup',handle:backupFileHandle,name:backupFileHandle.name,lastSavedAt:backupMeta.lastSavedAt,lastAutoFileAt:backupMeta.lastAutoFileAt});return true}catch(e){console.warn('file backup failed',e);return false}}
async function backup(){if(window.showSaveFilePicker){if(await writeBackupToHandle(true)){toast('تم تحديث النسخة الاحتياطية في مكانها المحفوظ.');renderNoAnim();return}if(await chooseBackup())return}const payload=backupPayload(),a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=u;a.download='OsRa_Backup_'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('تم تنزيل ملف النسخة الاحتياطية.')}
async function maybeAutoFileBackup(){if(!backupFileHandle)return;const week=7*24*60*60*1000;if(Date.now()-(backupMeta.lastAutoFileAt||0)<week)return;const ok=await writeBackupToHandle(false);if(ok){toast('تم تحديث النسخة الاحتياطية الدورية تلقائيًا.')}else{console.info('Automatic file backup skipped: permission needs user action.')}}
async function restoreSafety(){try{const s=await get('state','safetyBackup');if(!s?.value){toast('لا توجد نسخة أمان محلية بعد.');return}if(!confirm('استرجاع آخر نسخة أمان محلية واستبدال بيانات OsRa الحالية؟'))return;const x=s.value;if(x.app!=='OsRa')throw 0;state={...structuredClone(DEFAULT),...x,settings:{...DEFAULT.settings,...x.settings}};normalizeState();await save();if(Array.isArray(x.photoManifest)){for(const p of x.photoManifest){const old=photos.get(p.id)||{};const merged={...old,...p,excluded:!!p.excluded,thumbBlob:old.thumbBlob||null,thumbVersion:old.thumbVersion||0};await put('photos',merged);photos.set(p.id,merged)}}soundOn=!!state.settings.soundEnabled;toast('تم استرجاع نسخة الأمان المحلية. أعد ربط مكتبة الصور إذا لزم.');renderNoAnim()}catch(e){console.error(e);toast('تعذر استرجاع نسخة الأمان المحلية.')}}
function restore(){const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{try{const f=i.files?.[0];if(!f)return;const x=JSON.parse(await f.text());if(x.app!=='OsRa'||!Array.isArray(x.memories))throw 0;if(!confirm('استرجاع هذه النسخة واستبدال بيانات OsRa الحالية؟'))return;state={...structuredClone(DEFAULT),...x,settings:{...DEFAULT.settings,...x.settings}};normalizeState();await save();if(Array.isArray(x.photoManifest)){for(const p of x.photoManifest){const old=photos.get(p.id)||{};const merged={...old,...p,excluded:!!p.excluded,thumbBlob:old.thumbBlob||null,thumbVersion:old.thumbVersion||0};await put('photos',merged);photos.set(p.id,merged)}}soundOn=!!state.settings.soundEnabled;toast('تم استرجاع النسخة بنجاح. أعد ربط مكتبة الصور أو شغّل الفحص لتحديث الملفات.');renderNoAnim()}catch(e){console.error(e);toast('ملف النسخة الاحتياطية غير صالح أو تالف.')}};i.click()}
async function diagnostic(){const secure=!!isSecureContext,picker=!!window.showDirectoryPicker;let perm='لا يوجد مجلد';if(libraryHandle)try{perm=await libraryHandle.queryPermission({mode:'read'})}catch{}const e=await navigator.storage?.estimate?.();modal(`<h2>تشخيص OsRa</h2><div class="cards"><div class="card">HTTPS/secure: <b>${secure?'نعم':'لا'}</b></div><div class="card">اختيار المجلد: <b>${picker?'متاح':'غير متاح'}</b></div><div class="card">المجلد: <b>${libraryHandle?esc(libraryHandle.name||'مرتبط'):'غير مرتبط'}</b></div><div class="card">الإذن: <b>${esc(perm)}</b></div><div class="actions"><button class="btn primary" data-action="folder">${libraryHandle?'إعادة منح/تحديث إذن المجلد':'ربط مجلد الصور'}</button>${libraryHandle&&perm!=='granted'?'<button class="btn" data-action="grantPermission">منح الإذن الآن</button>':''}</div><div class="card">الصور المفهرسة: <b>${allPhotos().length}</b></div><div class="card">الذكريات: <b>${state.memories.length}</b></div><div class="card">التخزين المستخدم: <b>${e?.usage?Math.round(e.usage/1024/1024)+' MB':'غير معروف'}</b></div></div>`)}
function paperSound(){if(!soundOn)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const len=Math.floor(audioCtx.sampleRate*.24),buf=audioCtx.createBuffer(1,len,audioCtx.sampleRate),data=buf.getChannelData(0);for(let i=0;i<len;i++){const t=i/len;data[i]=(Math.random()*2-1)*Math.pow(1-t,2.2)*0.34}const src=audioCtx.createBufferSource(),filter=audioCtx.createBiquadFilter(),gain=audioCtx.createGain();src.buffer=buf;filter.type='bandpass';filter.frequency.value=2300;filter.Q.value=.55;gain.gain.setValueAtTime(.0001,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.18,audioCtx.currentTime+.025);gain.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.22);src.connect(filter).connect(gain).connect(audioCtx.destination);src.start();src.stop(audioCtx.currentTime+.24)}catch{}}
async function setSound(){soundOn=!soundOn;state.settings.soundEnabled=soundOn;await save();const b=$('#soundBtn');b.textContent=soundOn?'🔊':'🔇';b.classList.toggle('sound-on',soundOn);if(soundOn)paperSound()}
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-section]');if(b)go(b.dataset.section)});
document.addEventListener('change',e=>{const x=e.target.closest('.photo-select');if(!x)return;if(x.checked)selectedPhotos.add(x.dataset.photo);else selectedPhotos.delete(x.dataset.photo);updateSelectionCount()});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,i=b.dataset.id;try{
 if(a==='searchResult'){const type=b.dataset.type,rid=b.dataset.id;closeModal();if(type==='memory'){section='memories';renderNoAnim();setTimeout(()=>{const m=state.memories.find(x=>x.id===rid);if(m){currentMemoryId=m.id;$('#currentPage').innerHTML=pageMemory(m);hydrate()}},20)}else go(type==='message'?'messages':type==='dream'?'dreams':'spiritual');return}
 if(a==='go')go(b.dataset.section);else if(a==='folder')await chooseFolder();else if(a==='scan')await scan();else if(a==='search'){pageMemories.q=$('#searchMem').value;renderNoAnim()}else if(a==='addMemory')addMemory();else if(a==='newAlbum')newAlbum();else if(a==='saveAlbum')await saveAlbum();else if(a==='memory'){const m=state.memories.find(x=>x.id===i);if(m){currentMemoryId=m.id;section='memories';$('#currentPage').innerHTML=pageMemory(m);hydrate();setNav()}}else if(a==='shareMemory')await shareMemory(i);else if(a==='hideMemory')await hideMemory(i);else if(a==='unhideMemory')await unhideMemory(i);else if(a==='hiddenMemories')hiddenMemories();else if(a==='backMemories'){currentMemoryId=null;selectedPhotos.clear();renderNoAnim()}else if(a==='editMemory')editMemory(i);else if(a==='saveMemory')await saveMemory(i);else if(a==='photo')await openPhoto(i);else if(a==='selectAllPhotos')selectAllPhotos();else if(a==='clearPhotoSelection')clearPhotoSelection();else if(a==='removeFromAlbum')await removeFromAlbum();else if(a==='moveSelected')moveSelected();else if(a==='moveToAlbum')await moveToAlbum(i);else if(a==='createAlbumAndMove')createAlbumAndMove();else if(a==='saveAlbumMove')await saveAlbumMove(b.dataset.from,JSON.parse(b.dataset.ids||'[]'));else if(a==='excludeSelected')await excludeSelected();else if(a==='movePhotoUp')await reorderPhoto(i,-1);else if(a==='movePhotoDown')await reorderPhoto(i,1);else if(a==='restoreExcluded')await restoreExcluded();else if(a==='calendarDay'){calendarDate=b.dataset.date;calendarCursor=new Date(calendarDate+'T00:00:00');calendarCursor.setDate(1);renderNoAnim()}else if(a==='calendarPrev'){calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()-1,1);renderNoAnim()}else if(a==='calendarNext'){calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+1,1);renderNoAnim()}else if(a==='dream')dreamForm();else if(a==='editDream')dreamForm(state.dreams.find(x=>x.id===i));else if(a==='saveDream')await saveDream(i);else if(a==='verse')verseForm();else if(a==='saveVerse')await saveVerse();else if(a==='favVerse'){const x=state.verses.find(v=>v.id===i);if(x){x.favorite=!x.favorite;await save();renderNoAnim()}}else if(a==='delVerse'){state.verses=state.verses.filter(v=>v.id!==i);await save();renderNoAnim()}else if(a==='prayer')prayerForm();else if(a==='savePrayer')await savePrayer();else if(a==='togglePrayer'){const x=state.prayers.find(v=>v.id===i);if(x){x.done=!x.done;await save();renderNoAnim()}}else if(a==='message')msgForm();else if(a==='saveMessage')await saveMessage();else if(a==='toggleMessage'){const x=state.messages.find(v=>v.id===i);if(x){x.starred=!x.starred;await save();renderNoAnim()}}else if(a==='delMessage'){state.messages=state.messages.filter(v=>v.id!==i);await save();renderNoAnim()}else if(a==='event')eventForm();else if(a==='saveEvent')await saveEvent();else if(a==='settingsSave')await saveSettings();else if(a==='chooseBackup')await chooseBackup();else if(a==='backup')await backup();else if(a==='restore')restore();else if(a==='restoreSafety')await restoreSafety();else if(a==='diag')await diagnostic();else if(a==='grantPermission'){const ok=await permission();toast(ok?'تم منح إذن قراءة مجلد الصور.':'لم يتم منح الإذن.');await diagnostic()}else if(a==='closeModal')closeModal();
 }catch(err){console.error(err);toast('حدث خطأ. استخدم التشخيص إذا استمر.')}});
$('#modalClose').onclick=closeModal;$('#lbClose').onclick=closeLB;$('#lbPrev').onclick=async()=>{if(lb.i>0){lb.i--;await showPhoto()}};$('#lbNext').onclick=async()=>{if(lb.i<lb.ids.length-1){lb.i++;await showPhoto()}};
$('#book').addEventListener('touchstart',e=>{const t=e.changedTouches[0];$('#book').dataset.x=t.clientX;$('#book').dataset.y=t.clientY},{passive:true});$('#book').addEventListener('touchend',e=>{const t=e.changedTouches[0],x=+( $('#book').dataset.x||t.clientX),y=+( $('#book').dataset.y||t.clientY),dx=t.clientX-x,dy=t.clientY-y;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.2){const order=['home','memories','calendar','story','dreams','spiritual','messages','settings','about'],j=order.indexOf(section)+(dx<0?1:-1);if(j>=0&&j<order.length)navigate(order[j],dx<0?1:-1)}},{passive:true});
$('#searchBtn').onclick=()=>modal(`<h2>بحث في OsRa</h2><div class="field"><label>كلمة البحث</label><input id="globalQ"></div><button class="btn primary" id="runGlobal">بحث</button><div id="globalOut" style="margin-top:12px"></div>`);
document.addEventListener('click',e=>{if(e.target.id==='runGlobal'){const q=($('#globalQ').value||'').trim().toLowerCase(),o=[];if(!q){$('#globalOut').innerHTML='<div class="empty">اكتب كلمة للبحث.</div>';return}visibleMemories().filter(x=>[x.title,x.date,x.endDate,x.place,x.description].join(' ').toLowerCase().includes(q)).forEach(x=>o.push({type:'memory',id:x.id,icon:'📸',label:x.title,meta:rangeLabel(x)}));state.messages.filter(x=>[x.text,x.sender,x.date].join(' ').toLowerCase().includes(q)).forEach(x=>o.push({type:'message',id:x.id,icon:'✉',label:x.sender,meta:fmt(x.date)}));state.dreams.filter(x=>[x.title,x.note,x.targetDate].join(' ').toLowerCase().includes(q)).forEach(x=>o.push({type:'dream',id:x.id,icon:'🌱',label:x.title,meta:''}));state.verses.filter(x=>[x.text,x.ref].join(' ').toLowerCase().includes(q)).forEach(x=>o.push({type:'verse',id:x.id,icon:'☼',label:x.ref,meta:''}));$('#globalOut').innerHTML=o.length?o.map(x=>`<button class="card search-result" data-action="searchResult" data-type="${x.type}" data-id="${x.id}" style="width:100%;text-align:right;border:0;cursor:pointer"><b>${x.icon} ${esc(x.label)}</b>${x.meta?`<small class="meta">${esc(x.meta)}</small>`:''}<div class="meta">اضغط لفتح النتيجة</div></button>`).join(''):`<div class="empty">لا توجد نتائج.</div>`}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('#installBtn').hidden=false});window.addEventListener('appinstalled',()=>{installEvent=null;$('#installBtn').hidden=true});$('#installBtn').onclick=async()=>{if(!installEvent){toast('التثبيت غير متاح حاليًا من هذا المتصفح.');return}const e=installEvent;installEvent=null;await e.prompt();try{const r=await e.userChoice;$('#installBtn').hidden=r.outcome==='accepted'}catch{$('#installBtn').hidden=false}};
$('#soundBtn').onclick=setSound;
async function shareTarget(){const q=new URLSearchParams(location.search),text=(q.get('text')||'').trim(),title=(q.get('title')||'').trim(),url=(q.get('url')||'').trim();if(!(text||title||url))return;history.replaceState({},document.title,location.pathname);const body=[text,url].filter(Boolean).join('\n')||title;setTimeout(()=>{msgForm();setTimeout(()=>{if($('#msgText'))$('#msgText').value=body;if($('#msgSender'))$('#msgSender').value='واتساب'},30)},250)}
(async()=>{try{await dbOpen();await load();renderNoAnim();if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>null);reg?.update?.().catch(()=>{});}const sb=$('#soundBtn');if(sb){sb.textContent=soundOn?'🔊':'🔇';sb.classList.toggle('sound-on',soundOn)}await shareTarget();await maybeAutoFileBackup();setInterval(()=>{maybeAutoFileBackup().catch(()=>{})},6*60*60*1000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')maybeAutoFileBackup().catch(()=>{})})}catch(e){console.error(e);toast('تعذر تشغيل OsRa.')}})();
